-- UPSC CSE Prelims PYQ Complete Collection (1995-2025)
-- 3,897 Vectorized & Indexed MCQs for PostgreSQL 16 + pgvector

CREATE TABLE IF NOT EXISTS prelims_pyqs (
    id BIGSERIAL PRIMARY KEY,
    exam_year INT NOT NULL,
    subject VARCHAR(100) NOT NULL,
    subtopic VARCHAR(150),
    difficulty VARCHAR(20) DEFAULT 'moderate',
    question_number INT NOT NULL,
    question_text TEXT NOT NULL,
    correct_answer VARCHAR(5),
    embedding vector(768),
    search_vector tsvector
);

CREATE INDEX IF NOT EXISTS idx_prelims_embedding ON prelims_pyqs USING hnsw (embedding vector_cosine_ops);
CREATE INDEX IF NOT EXISTS idx_prelims_tsvector ON prelims_pyqs USING gin(search_vector);
CREATE INDEX IF NOT EXISTS idx_prelims_year ON prelims_pyqs(exam_year);
CREATE INDEX IF NOT EXISTS idx_prelims_subject ON prelims_pyqs(subject);

