INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2025, 'Indian Economy', 'Fiscal Policy & Budget', 'moderate', 66,
    'Which of the following statements with regard to recommendations of the 15th Finance
Commission of India are correct?
