INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2024, 'Indian Polity', 'Federalism & Centre–State Relations', 'moderate', 75,
    'Which one of the following statements is correct as per the Constitution of India ?
(a) Inter-State trade and commerce is a State subject under the State List
