INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2023, 'Indian Polity', 'Constitutional Framework & Development', 'easy', 33,
    'Which one of the following statements best reflects the Chief purpose of the ''Constitution''
of a country?
(a) It determines the objective for the making of necessary laws.
