INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2022, 'Environment & Ecology', 'Climate Change & Greenhouse Gases', 'easy', 21,
    'Among the following crops, which one is the most important anthropogenic source of both
methane and nitrous oxide?
(a) Cotton
