INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2022, 'Science & Technology', 'Health & Diseases', 'moderate', 39,
    'In the context of vaccines manufactured to prevent COVID-19 pandemic, consider the
following statements:
