INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2022, 'Modern History', 'Constitutional Developments & British Plans (1909-1947)', 'moderate', 51,
    'In the Government of India Act 1919, the functions of Provincial Government were divided
