INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2022, 'Indian Polity', 'Federalism & Centre–State Relations', 'easy', 73,
    'If a particular area is brought under the Fifth Schedule of the Constitution of India, which
one of the following statements best reflects the consequence of it?
(a) This would prevent the transfer of land of tribal people to non-tribal people.
