INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2021, 'Indian Economy', 'Fiscal Policy & Budget', 'easy', 3,
    'Which among the following steps is most likely to be taken at the time of an economic
recession?
(a) Cut in tax rates accompanied by increase in interest rate
