INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2021, 'Modern History', 'Gandhian Mass Movements (1915-1942)', 'easy', 43,
    'With reference to 8th August, 1942 in Indian history, which one of the following statements
