INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2020, 'Environment & Ecology', 'Environmental Governance & Legislation', 'easy', 81,
    'If a particular plant species is placed under Schedule VI of The Wildlife Protection Act, 1972,
what is the implication?
(a) A licence is required to cultivate that plant.
