INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2019, 'Modern History', 'Gandhian Mass Movements (1915-1942)', 'moderate', 14,
    'With reference to the British colonial rule in India, consider the following statements:
