INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2019, 'Indian Economy', 'International Institutions & Reports', 'moderate', 71,
    'With reference to Asian Infrastructure Investment Bank (AIIB), consider the following
statements:
