INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2018, 'Science & Technology', 'Computer & Information Technology', 'moderate', 17,
    'The identity platform ''Aadhaar'' provides open ''Application Programming Interfaces (APIs)''.
