INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2018, 'Science & Technology', 'Energy & Environment', 'moderate', 33,
    'In the Indian context, what is the implication of ratifying the ‘Additional Protocol’ with the
‘International Atomic Energy Agency (IAEAY ?
(a) The civilian nuclear reactors come under IAFA safeguards.
