INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2018, 'Environment & Ecology', 'Sustainable Agriculture & Forestry', 'moderate', 35,
    'With reference to the ''Global Alliance for Climate-Smart Agriculture (GACSA)'', which of the
following statements is/are correct?
