INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2018, 'Indian Economy', 'National Income & Economic Growth', 'moderate', 47,
    'If a commodity is provided free to the public by the Government, then
(a) the opportunity cost is zero.
