INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2018, 'Indian Polity', 'Emergency Provisions', 'moderate', 53,
    'If the President of India exercises his power as provided under Article 356 of the
Constitution in respect of a particular State, then
(a) the Assembly of the State is automatically dissolved.
(b) the powers of the Legislature of that State shall be exercisable by or under the authority of the
