INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2018, 'Modern History', 'Gandhian Mass Movements (1915-1942)', 'easy', 69,
    'Which one of the following is a very significant aspect of the Champaran Satyagraha?
