INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2017, 'Indian Economy', 'Human Development, Poverty & Employment Schemes', 'moderate', 3,
    '''Recognition of Prior Learning Scheme'' is sometimes mentioned in the news with reference to
(a) Certifying the skills acquired by construction workers through traditional channels.
