INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2017, 'Modern History', 'Early Nationalism & Indian National Congress (1885-1915)', 'moderate', 19,
    'At one of the places in India, if you stand on the seashore and watch the sea, you will find
that the sea water recedes from the shore line a few kilometres and comes back to the shore,
twice a day, and you can actually walk on the sea floor when the water recedes. This unique
phenomenon is seen at
(a) Bhavnagar
