INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2017, 'Indian Economy', 'Human Development, Poverty & Employment Schemes', 'easy', 29,
    'Who among the following can join the National Pension System (NPS)?
(a) Resident Indian citizens only
(b) Persons of age from 21 to 55 only
(c) All State Government employees joining the services after the date of notification by the
