INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2017, 'Indian Polity', 'Political Theory & Concepts', 'easy', 47,
    'In the context of India,
which one of the following is the correct relationship between Rights and Duties?
(a) Rights are correlative with Duties.
