INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2016, 'Science & Technology', 'Energy & Environment', 'easy', 79,
    'India is an important member of the ‘International Thermonuclear Experimental Reactor’. If
this experiment succeeds, what is the immediate advantage for India?
