INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2016, 'Indian Polity', 'Federalism & Centre–State Relations', 'moderate', 95,
    'The Parliament of India acquires the power to legislate on any item in the State List in the
national interest if a resolution to that effect is passed by the
(a) Lok Sabha by a simple majority of its total membership
