INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2015, 'Indian Polity', 'Directive Principles Of State Policy', 'easy', 7,
    'Consider the following statements regarding the Directive Principles of State Policy:
