INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2014, 'Environment & Ecology', 'Environmental Governance & Legislation', 'moderate', 5,
    'With reference to Bombay Natural History Society (BNHS), consider the following statements:
1. It is an autonomous organization under the Ministry of Environment and Forests.
