INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2014, 'Environment & Ecology', 'Climate Change & Greenhouse Gases', 'moderate', 79,
    'Consider the following statements regarding ''Earth Hour'':
1. It is an initiative of UNEP and UNESCO.
