INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2014, 'Indian Economy', 'Agriculture & Rural Development', 'moderate', 94,
    'In the context of food and nutritional security of India, enhancing the ‘Seed Replacement
