INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2013, 'Indian Polity', 'Parliament & State Legislatures', 'moderate', 1,
    'What will follow if a Money Bill is substantially amended by the Rajya Sabha?
(a) The Lok Sabha may still proceed with the Bill, accepting or not accepting the recommendations
of the Rajya Sabha
