INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2012, 'Science & Technology', 'Space Technology & Astronomy', 'moderate', 19,
    'Which of the following is/are cited by the scientists as evidence/evidences for the continued
