INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2012, 'Indian Polity', 'Local Government & Panchayati Raj', 'moderate', 23,
    'Which of the following can be said to be essentially the parts of Inclusive Governance?
