INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2012, 'Modern History', 'Gandhian Mass Movements (1915-1942)', 'moderate', 25,
    'The Congress ministries resigned in the seven provinces in 1939, because
(a) the Congress could not form ministries in the other four provinces
