INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2012, 'Geography', 'Atmosphere & Climatology', 'moderate', 49,
    'Normally, the temperature decreases with the increase in height from the Earth''s surface,
because
1. The atmosphere can be heated upwards only from the Earth''s surface.
