INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2012, 'Indian Polity', 'Union & State Executive', 'easy', 53,
    'The Prime Minister of India, at the time of his/her appointment
(a) need not necessarily be a member of one of the Houses of the Parliament but must become a
member of one of the Houses within six months
(b) need not necessarily be a member of one of the Houses of the Parliament but must become a member
