INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2012, 'Indian Economy', 'Agriculture & Rural Development', 'moderate', 58,
    'How do District Rural Development Agencies (DRDAs) help in the reduction of rural poverty
