INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2012, 'Art & Culture', 'Sculpture & Iconography', 'easy', 72,
    'Lord Buddha''s image is sometimes shown with the hand gesture called ''Bhumisparsha
Mudra''. It symbolizes
(a) Buddha''s calling of the Earth to watch over Māra and to prevent Māra from disturbing his meditation
(b) Buddha''s calling of the Earth to witness his purity and chastity despite the temptations of Māra
(c) Buddha''s reminder to his followers that they all arise from the Earth and finally dissolve into the Earth,
and, thus this life is transitory
