INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2012, 'Indian Economy', 'Monetary Policy & Money Supply', 'moderate', 77,
    'Which of the following measures would result in an increase in the money supply in the
economy?
1. Purchase of government securities from the public by the Central Bank
2. Deposit of currency in commercial banks by the public
