INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2012, 'Indian Economy', 'Infrastructure & Industry', 'moderate', 84,
    'Despite having large reserves of coal, why does India import millions of tonnes of coal?
