INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2012, 'Geography', 'Astronomy & Earth–Sun System', 'easy', 85,
    'A person stood alone in a desert on a dark night and wanted to reach his village which was
situated 5 km east of the point where he was standing. He had no instruments to find the
direction but he located the pole star. The most convenient way now to reach his village is to
walk in the
(a) direction facing the pole star
