INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2011, 'Environment & Ecology', 'Pollution & Waste Management', 'moderate', 9,
    'The formation of ozone hole in the Antarctic region has been a cause of concern. What could
be the reason for the formation of this hole?
(a) Presence of prominent tropospheric turbulence; and inflow of chlorofluorocarbons
