INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2011, 'Science & Technology', 'Biotechnology & Genetics', 'easy', 29,
    'A genetically engineered form of brinjal, known as the Bt-brinjal, has been developed. The
objective of this is
(a) To make it pest-resistant
