INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2011, 'Indian Polity', 'Parliament & State Legislatures', 'easy', 43,
    'When the annual Union Budget is not passed by the Lok Sabha,
(a) the Budget is modified and presented again
