INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2011, 'Science & Technology', 'Computer & Information Technology', 'easy', 57,
    'What is the difference between Bluetooth and Wi-Fi devices ?
(a) Bluetooth uses 2.4 GHz radio frequency band, whereas Wi-Fi can use 2.4 GHz or 5 GHz frequency
band
(b) Bluetooth is used for Wireless Local Area Networks (WLAN) only, whereas Wi-Fi is used for Wireless
Wide Area Networks (WWAN) only
(c) When information is transmitted between two devices using Bluetooth technology, the devices have to
