INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2011, 'Modern History', 'Early Nationalism & Indian National Congress (1885-1915)', 'moderate', 63,
    'What was the purpose with which Sir William Wedderburn and W. S. Caine had set up the
Indian Parliamentary Committee in 1893?
(a) To agitate for Indian political reforms in the House of Commons
