INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2011, 'Environment & Ecology', 'Biodiversity & Conservation', 'moderate', 79,
    'The "Red Data Books" published by the International Union for Conservation of Nature and
Natural Resources (IUCN) contain lists of
1. Endemic plant and animal species present in the biodiversity hotspots.
