INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2010, 'Science & Technology', 'Biotechnology & Genetics', 'moderate', 5,
    'Mon 863 is a variety of maize. It was in the news for the following reason
(a) It is a genetically modified dwarf variety which is resistant to drought
