INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2010, 'Science & Technology', 'Chemistry', 'easy', 11,
    'Chlorination is a process used for water purification. The disinfecting action of chlorine is
mainly due to
(a) The formation of hydrochloric acid when chlorine is added to water
