INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2010, 'Science & Technology', 'Physics', 'easy', 27,
    'Two trains leave New Delhi at the same time. One travels north at 60 kmph and the other
travels south at 40 kmph. After how many hours will the trains be 150 km apart?
