INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2010, 'Geography', 'Economic & Mineral Geography', 'moderate', 47,
    'With reference to the mineral resources of India, consider the following pairs:
Mineral — 90% Natural sources in
1. Copper  —  Jharkhand
