INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2010, 'Environment & Ecology', 'Ecosystems & Ecology Concepts', 'easy', 65,
    'Some species of plants are insectivorous. Why ?
(a) Their growth in shady and dark places does not allow them to undertake sufficient photosynthesis and
thus they depend on insects for nutrition.
(b) They are adapted to grow in nitrogen deficient soils and thus depend on insects for sufficient
nitrogenous nutrition.
