INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2010, 'Environment & Ecology', 'Ecosystems & Ecology Concepts', 'easy', 103,
    'King Cobra is the only snake that makes its own nest. Why does it make its nest?
(a) It is a snake-eater and the nest helps attract other snakes
