INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2010, 'Indian Economy', 'Fiscal Policy & Budget', 'moderate', 134,
    'With reference to the National Investment Fund to which the disinvestment proceeds are
