INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2010, 'Indian Economy', 'Banking & Financial Sector', 'moderate', 137,
    'With reference to the institution of Banking Ombudsman in India, which one of the
statements is not correct ?
