INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2009, 'Science & Technology', 'Quantitative Aptitude', 'moderate', 106,
    'In a carrom board game competition, m boys and n girls (m > n > 1) of a school participate
