INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2008, 'Science & Technology', 'Quantitative Aptitude', 'moderate', 5,
    'A person purchases 100 pens at a discount of 10%. The net amount of money spent by the
person to purchase the pens is Rs 600. The selling expenses incurred by the person are 15% on
the net cost price. What should be the selling price for 100 pens in order to earn a profit of 25%?
