INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2008, 'Indian Polity', 'Parliament & State Legislatures', 'moderate', 100,
    'Consider the following statements:
The Constitution of India provides that
1. The Legislative Assembly of each State shall consist of not more than 450 members chosen by
direct election from territorial constituencies in the State
2. A person shall not be qualified to be chosen to fill a seat in the Legislative Assembly of a State if
he/she is less than 25 years of age
