INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2007, 'Indian Polity', 'Constitutional Framework & Development', 'easy', 51,
    'Which of the Constitution Amendment Acts seeks that the size of the Council of Ministers at
the Centre and in a State must not exceed 15 percent of the total number in the Lok Sabha and
the total number of members of the Legislative Assembly of that State, respectively?
(a) 91st
