INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2007, 'Science & Technology', 'Quantitative Aptitude', 'moderate', 147,
    'Amit starts from a point A, walks to another point B and then returns from B to A by his car,
taking a total time of 6 hours 45 minutes. If he had driven both ways in his car, he would have
taken 2 hours less. How long would it take for him to walk both ways?
(a) 7 hours 45 minutes
