INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2006, 'Science & Technology', 'Quantitative Aptitude', 'moderate', 56,
    'Each of 8 identical balls is to be placed in the squares shown in the figure given above in a
horizontal direction such that one horizontal row contains 6 balls and the other horizontal row
contains 2 balls. In how many maximum different ways can this be done?
(a) 38
