INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2006, 'Science & Technology', 'Quantitative Aptitude', 'easy', 62,
    'A box contains 5 sets of balls while there are 3 balls in each set. Each set of balls has one
colour which is different from every other set. What is the least number of balls that must be
removed from the box in order to claim with certainty that a pair of balls of the same colour has
been removed?
(a) 6
