INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2006, 'Medieval History', 'Delhi Sultanate', 'easy', 74,
    'Which one of the following is the correct chronological order of the Afghan rulers to the
throne of Delhi?
(a) Sikandar Shah-Ibrahim Lodi-Bahlol Khan Lodi
