INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2006, 'Science & Technology', 'Logical Reasoning & Puzzles', 'moderate', 103,
    'In an office, the number of persons who take tea is twice the number of persons who take
only coffee. The number of persons who take coffee is twice the number of persons who take
only tea.
