INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2005, 'Environment & Ecology', 'International Environmental Treaties & Summits', 'moderate', 138,
    'Which one of the following statements is correct?
(a) The First Meeting of the Parties (MOP-1) to the Cartagena Protocol on Biosafety was held in the
Philippines in 2004.
