INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2005, 'Geography', 'Population & Demography', 'moderate', 146,
    'Which one of the following statements is not correct?
(a) There is no definition of the Scheduled Tribe in the Constitution of India.
