INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2004, 'Ancient History', 'Buddhism & Jainism', 'moderate', 26,
    'With reference to ancient Jainism,
which one of the following statements is correct?
(a) Jainism was spread in South India under the leadership of Sthalabahu
(b) The Jains who remained under the leadership of Bhadrabahu were called Svetambaras after the Council
