INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2004, 'Science & Technology', 'Physics', 'easy', 106,
    'A car is running on a road at a uniform speed of 60 km/hr. The net resultant force on the
car is
(a) Driving force in the direction of car’s motion
