INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2003, 'Science & Technology', 'Quantitative Aptitude', 'easy', 44,
    'A car travels the first one-third of a certain distance with a speed of 10 km/hr, the next
one-third distance with a speed of 20 km/hr and the last one-third distance with a speed of 60
km/hr. The average speed of the car for the whole journey is
(a) 18 km/hr
