INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2002, 'Modern History', 'Constitutional Developments & British Plans (1909-1947)', 'moderate', 54,
    'The real intention of the British to include the princely states in the Federal Union proposed
by the India Act of 1935 was to
(a) exercise more and direct political and administrative control over the princely states
