INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2002, 'Indian Economy', 'External Sector & Balance Of Payments', 'easy', 70,
    'Global capital flows to developing countries increased significantly during the nineties. In
view of the East Asian financial crisis and the Latin American experience, which type of inflow is
considered safest for the host country?
