INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2002, 'Science & Technology', 'Chemistry', 'hard', 110,
    'Match List I (Oxidation number) with List II (The element) and select the correct answer
using the codes given below the lists:
List I (Oxidation number) — List II (The element)
A. 2 —
1. Oxidation number of Mn in MnO₂
B. 3 —
2. Oxidation number of S in H₂S₂O₇
C. 4 —
3. Oxidation number of Ca in CaO₂
D. 6 —
4. Oxidation number of Al in NaAlH₄
(a) A-3, B-4, C-1, D-2
