INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2001, 'Indian Polity', 'Constitutional & Statutory Bodies', 'moderate', 86,
    'Which one of the following duties is NOT performed by the Comptroller and Auditor General
of India?
(a) To audit and report on all expenditure from the Consolidated Fund of India
(b) To audit and report on all expenditure from the Contingency Funds and Public Accounts
