INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2000, 'Geography', 'World Political Geography & Borders', 'moderate', 44,
    'Consider the following provinces of former Yugoslavia:
I. Bosnia
II. Croatia
III. Slovenia
IV. Yugoslavia
The correct sequence of these provinces from the east to the west is
(a) IV, I, III, II
