INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2000, 'Indian Polity', 'Local Government & Panchayati Raj', 'easy', 68,
    'The 73rd Constitution Amendment Act, 1992 refers to the
(a) generation of gainful employment for the unemployed and the underemployed men and women in
rural area
(b) generation of employment for the able-bodied adults who are in need and desirous of work during the
lean agricultural season
