INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2000, 'Indian Economy', 'National Income & Economic Growth', 'easy', 94,
    'In an open economy, the national income (Y) of the economy is: (C, I, G, X, M stand for
Consumption, Investment, Government Expenditure, total exports and total imports
respectively.)
(a) Y = C + I + G + X
