INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2000, 'Science & Technology', 'Physics', 'moderate', 114,
    'Assertion (A): Large cold storage plants use ammonia as refrigerant while domestic
refrigerators use chlorofluorocarbons.
Reason (R): Ammonia can be liquified at ambient temperatures at low pressures.
(a) Both A and R are true, and R is the correct explanation of A
