INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    2000, 'Environment & Ecology', 'Ecosystems & Ecology Concepts', 'easy', 126,
    'Within biological communities, some species are important in determining the ability of a
large number of other species to persist in the community. Such species are called
(a) Keystone species
