INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    1999, 'Indian Economy', 'Infrastructure & Industry', 'moderate', 56,
    'The product life cycle from inception to demise is shown in the graph. Match List I with List
II
and select the correct answer using the codes given below the Lists:
