INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    1999, 'Science & Technology', 'Quantitative Aptitude', 'moderate', 134,
    'The average speed of a train in the onward journey is 25% more than that of the return
journey. The train halts for one hour on reaching the destination. The total time taken for the
complete to-and-fro journey is 17 hours covering a distance of 800 km. The speed of the train in
the onward journey is
(a) 45 km per hour
