INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    1999, 'Science & Technology', 'Quantitative Aptitude', 'moderate', 150,
    'Amar, Akbar and Anthony are friends, being looked after by a matron Farah. Amar weighs
50% more than Akbar and Anthony weigh 25% less than Amar. Farah weighs a third of the
combined weight of the three boys. All four together weigh 232 kg. The correct arrangement of
the persons in the ascending order of their weights is
(a) Anthony, Akbar, Farah, Amar
