INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    1998, 'Modern History', 'Early Nationalism & Indian National Congress (1885-1915)', 'moderate', 30,
    'Assertion (A): Partition of Bengal in 1905 brought to an end the Moderates’ role in the Indian
freedom movement.
