INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    1998, 'Indian Economy', 'Inflation & Price Indices', 'moderate', 131,
    'The misery index is the sum of a country’s unemployment and inflation rate. The higher the
