INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    1997, 'Indian Polity', 'Local Government & Panchayati Raj', 'moderate', 20,
    'Which one of the following was NOT proposed by the 73rd Constitutional Amendment in the
area of Panchayati Raj?
(a) Thirty per cent seats in all elected rural local bodies will be reserved for women candidates at all levels
(b) The States will constitute their Finance Commissions to allocate resources to Panchayati Raj Institutions
(c) The Panchayati Raj elected functionaries will be disqualified to hold their offices if they have
