INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    1997, 'Indian Polity', 'Union & State Executive', 'moderate', 66,
    'In the Presidential election in India, every elected member of the Legislative Assembly of a
State shall have as many votes as there are multiples of one thousand in the quotient obtained
by dividing the population of the State by the total number of the elected members of the
Assembly. As at present (1997) the expression "population" here means the population as
ascertained by the
(a) 1991 Census
