INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    1997, 'Science & Technology', 'Physics', 'easy', 144,
    'A girl is swinging on a swing in sitting position. When the same girl stands up, the period of
swing will
(a) be shorter
