INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    1996, 'Modern History', 'Constitutional Developments & British Plans (1909-1947)', 'moderate', 1,
    'The meeting of Indian and British political leaders during 1930-32 in London has often been
referred to as the First, Second and Third Round Table Conferences. It would be incorrect to refer
to them as such because
(a) the Indian National Congress did not take part in two of them
(b) Indian parties other than the Indian National Congress participating in the Conference represented
sectional interests and not the whole of India
(c) the British Labour Party had withdrawn from the Conference, thereby making the proceedings of the
Conference partisan
(d) it was an instance of Conference held in three sessions and not that of three separate
