INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    1996, 'Indian Economy', 'Fiscal Policy & Budget', 'easy', 2,
    'A redistribution of income in a country can be best brought about through
(a) progressive taxation combined with progressive expenditure
