INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    1996, 'Current Affairs', 'International Organisations & Groupings', 'moderate', 80,
    '‘They are fantastically diverse. They speak hundreds of languages and dialects. They
comprise scores of ethnic groups. They include highly industrialised economies and
up-and-coming economies. They span half the surface of the earth and are home to two-fifths of
the world’s population.’ The group of countries referred to belongs to
(a) SAPTA
