INSERT INTO prelims_pyqs (exam_year, subject, subtopic, difficulty, question_number, question_text, correct_answer, embedding, search_vector) VALUES (
    1996, 'Indian Economy', 'External Sector & Balance Of Payments', 'moderate', 140,
    'The changing composition of the export trade is indicative of structural transformation of
Indian economy in favour of modernisation. The best indicator of the trend is the
(a) relative share of petroleum products in exports
